{
  "description": "A quadrupedal chimera shown in right-facing profile standing on a small patch of sandy, pebbly ground. The front is a gray and white wolf with a long muzzle, black nose, amber eyes, and thick fur around the cheeks, throat and chest, while the rest of the body is covered in dark gray, pitted, segmented armor resembling a crab or lobster. A large domed carapace with a scalloped, slightly upturned edge and surface scratches and barnacle-like bumps covers the back and sides, and a row of pointed, overlapping plates forms a spiny crest along the dorsal midline from the neck to the mid-back. The two forelimbs are thick, heavily armored and end in large dark pincers that rest on the ground, and the two hind limbs are thick, jointed and armored and end in clawed feet. A long, tapering, ring-segmented armored tail extends from the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a wolf-like head with gray and white fur, a long pointed muzzle, black nose, amber eyes with dark pupils, and white fur around the mouth and lower jaw",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two upright triangular ears covered in gray and white fur with dark interiors and light fur on the rims",
      "where": "on top of the head, one on each side of the midline"
    },
    {
      "part": "legs",
      "looks_like": "four thick jointed legs covered in overlapping dark gray armored plates with light edges and pitted surfaces; the front pair are more massive and end in large pincers, the hind pair are slightly narrower and end in toed feet",
      "where": "underneath the torso, two at the front and two at the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "front feet are large dark crab-like pincers with two curved black-tipped fingers and small bumps and barnacle spots on the surface; hind feet are broad scaly paws with four toes each bearing dark curved claws",
      "where": "at the bottom ends of the legs contacting the ground, pincers at the front, clawed paws at the rear"
    },
    {
      "part": "tail",
      "looks_like": "a long tapering tail made of many overlapping ring-like armored segments with a pointed tip, dark on top and lighter underneath",
      "where": "extending from the rear left end of the body, behind the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "a large dark gray domed carapace with a scalloped lower margin, surface scratches, pits and small circular bumps, covering the torso like a shield",
      "where": "on the back and upper sides of the torso, from behind the shoulders to above the hindquarters"
    },
    {
      "part": "plates",
      "looks_like": "numerous overlapping hard dark gray plates with pale edges and pitted surfaces; neck plates are spiky and form a dorsal crest, leg and tail plates are ring-like and segmented, and a small three-lobed plate caps the forehead",
      "where": "covering the neck, back, sides, legs, tail, and top of the head between the ears"
    }
  ],
  "attached_objects": [],
  "animals": [
    "wolf",
    "crab"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
